        for (Pool p : all) {
            membersOf.put(p.getId(), byPool.getOrDefault(p.getId(), List.of()).stream()
                    .filter(m -> m.getPersonId() != null ? byId.containsKey(m.getPersonId())
                            : poolsById.containsKey(m.getMemberPoolId()))
